05-break-e-continue.md.codigo_inicial:
for numero in range(1, 9):
    # Pule 3 e encerre quando chegar a 6.
    print(numero)

05-break-e-continue.md.correcao:
for numero in range(1, 9):
    if numero == 3:
        continue  # Pule só a volta atual.
    if numero == 6:
        break  # Encerre o laço antes de imprimir 6.
    print(numero)

